// generar_311_chequeo_abre_visita_directa.js
// CHIQUI Entre Señales — "Chequeo preventivo" abre directo el formulario de visita
//
// Antes, tocar "Chequeo preventivo" en Próximos llevaba a la página de
// Salud (y ahí había que buscar la sección y tocar "Agregar visita").
// Ahora lleva DIRECTO al formulario de nueva visita veterinaria, ya
// abierto y listo para llenar.
//
// Cómo funciona:
//   · El dashboard enlaza a /prevencion?nuevaVisita=1
//   · El componente VisitasVeterinarias detecta ese parámetro al cargar
//     (useSearchParams) y despliega la sección + abre el formulario de
//     nueva visita automáticamente.
//
// Detalle técnico: useSearchParams necesita un límite de Suspense en
// Next.js, así que el componente de visitas queda envuelto en <Suspense>
// dentro de la página de Salud (evita el error de build de Vercel).
//
// No hay SQL.
//
// Uso:
//   node generar_311_chequeo_abre_visita_directa.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "components/VisitasVeterinarias.tsx",
    base64: ""
  },
  {
    ruta: "app/prevencion/page.tsx",
    base64: ""
  },
  {
    ruta: "app/dashboard/page.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 3 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
